(26379, 2888, 'text', '雙廂鐵床', NULL, 100),
(26380, 2888, 'text', '6速手排', NULL, 110),
(26381, 2888, 'text', '雙廂鐵床', NULL, 120),
(26382, 2888, 'text', '5速手自排', NULL, 130),
