(30575, 3375, 'text', '熱量：38kcal', NULL, 110),
(30576, 3375, 'text', '膳食纖維：1.3g', NULL, 120),
(30577, 3375, 'text', '維他命C：57.8mg', NULL, 130),
(30578, 3375, 'text', '礦物質鉀：175mg', NULL, 140),
(30579, 3375, 'text', '白柚', NULL, 150),
(30580, 3375, 'text', '熱量：36kcal', NULL, 160),
