    NEW.total_heat <=> OLD.total_heat
)
THEN
    UPDATE relation_data
    SET total_news_heat = total_news_heat + ( NEW.total_heat - OLD.total_heat )
    WHERE relation_id = NEW.relation_id;
END IF
$$
