    (NEW.eventsorting_id <=> OLD.eventsorting_id) AND
    (NEW.multipleperspectives_id <=> OLD.multipleperspectives_id)
)
THEN
    IF (
        ( (NEW.news_id IS NOT NULL) + 
          (NEW.channel_id IS NOT NULL) + 
          (NEW.eventsorting_id IS NOT NULL) + 
          (NEW.multipleperspectives_id IS NOT NULL)
        ) != 1
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Exactly one of news_id, channel_id, eventsorting_id, multipleperspectives_id must be NOT NULL';
    END IF;
END IF
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `delete_action (ad_user_score)` AFTER DELETE ON `user_score` FOR EACH ROW BEGIN
    -- news
    IF OLD.news_id IS NOT NULL
    THEN
        UPDATE news_data
        SET total_score = GREATEST(total_score - OLD.target_score, 0),
        	total_rater = GREATEST(total_rater - 1, 0)
        WHERE news_id = OLD.news_id;
    END IF;
    
	-- channel
    IF OLD.channel_id IS NOT NULL
    THEN
        UPDATE channel_data
        SET total_score = GREATEST(total_score - OLD.target_score, 0),
        	total_rater = GREATEST(total_rater - 1, 0)
        WHERE channel_id = OLD.channel_id;
    END IF;
    
    -- eventsorting
    IF OLD.eventsorting_id IS NOT NULL
    THEN
        UPDATE eventsorting_data
        SET total_score = GREATEST(total_score - OLD.target_score, 0),
        	total_rater = GREATEST(total_rater - 1, 0)
        WHERE eventsorting_id = OLD.eventsorting_id;
    END IF;
    
	-- multipleperspectives
    IF OLD.multipleperspectives_id IS NOT NULL
    THEN
        UPDATE multipleperspectives_data
        SET total_score = GREATEST(total_score - OLD.target_score, 0),
        	total_rater = GREATEST(total_rater - 1, 0)
        WHERE multipleperspectives_id = OLD.multipleperspectives_id;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `insert_action (ai_user_score)` AFTER INSERT ON `user_score` FOR EACH ROW BEGIN
    -- news
    IF NOT(
        NEW.news_id <=> NULL
    ) THEN
        UPDATE news_data
        SET total_score = total_score + NEW.target_score,
        	total_rater = total_rater + 1
        WHERE news_id = NEW.news_id;
    END IF;
    
	-- channel
    IF NOT(
        NEW.channel_id <=> NULL
    ) THEN
        UPDATE channel_data
        SET total_score = total_score + NEW.target_score,
        	total_rater = total_rater + 1
        WHERE channel_id = NEW.channel_id;
    END IF;
    
    -- eventsorting
    IF NOT(
        NEW.eventsorting_id <=> NULL
    ) THEN
        UPDATE eventsorting_data
        SET total_score = total_score + NEW.target_score,
        	total_rater = total_rater + 1
        WHERE eventsorting_id = NEW.eventsorting_id;
    END IF;
    
	-- multipleperspectives
    IF NOT(
        NEW.multipleperspectives_id <=> NULL
    ) THEN
        UPDATE multipleperspectives_data
        SET total_score = total_score + NEW.target_score,
        	total_rater = total_rater + 1
        WHERE multipleperspectives_id = NEW.multipleperspectives_id;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `limit_update (bu_user_score)` BEFORE UPDATE ON `user_score` FOR EACH ROW IF (NOT (NEW.score_id                <=> OLD.score_id) OR
	NOT (NEW.user_id                 <=> OLD.user_id) OR
	NOT (NEW.news_id                 <=> OLD.news_id) OR
	NOT (NEW.channel_id              <=> OLD.channel_id) OR
	NOT (NEW.eventsorting_id         <=> OLD.eventsorting_id) OR
	NOT (NEW.multipleperspectives_id <=> OLD.multipleperspectives_id)) 
THEN
	SIGNAL SQLSTATE '45000'
	SET MESSAGE_TEXT = 'Only target_score can be updated';
END IF
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `update_action (au_user_score)` AFTER UPDATE ON `user_score` FOR EACH ROW BEGIN
    -- news
    IF (OLD.news_id IS NOT NULL AND 
		NOT (OLD.target_score <=> NEW.target_score))
    THEN
        UPDATE news_data
        SET total_score = GREATEST(COALESCE(total_score + NEW.target_score - OLD.target_score, 0), 0)
        WHERE news_id = OLD.news_id;
    END IF;
    
	-- channel
    IF (OLD.channel_id IS NOT NULL AND 
		NOT (OLD.target_score <=> NEW.target_score))
    THEN
        UPDATE channel_data
        SET total_score = GREATEST(COALESCE(total_score + NEW.target_score - OLD.target_score, 0), 0)
        WHERE channel_id = OLD.channel_id;
    END IF;
    
    -- eventsorting
    IF (OLD.eventsorting_id IS NOT NULL AND 
		NOT (OLD.target_score <=> NEW.target_score))
    THEN
        UPDATE eventsorting_data
        SET total_score = GREATEST(COALESCE(total_score + NEW.target_score - OLD.target_score, 0), 0)
        WHERE eventsorting_id = OLD.eventsorting_id;
    END IF;
    
	-- multipleperspectives
    IF (OLD.multipleperspectives_id IS NOT NULL AND 
		NOT (OLD.target_score <=> NEW.target_score))
    THEN
        UPDATE multipleperspectives_data
        SET total_score = GREATEST(COALESCE(total_score + NEW.target_score - OLD.target_score, 0), 0)
        WHERE multipleperspectives_id = OLD.multipleperspectives_id;
    END IF;
END
$$
DELIMITER ;

