DELIMITER $$
--
-- 事件
--
CREATE DEFINER=`root`@`localhost` EVENT `update_recent_heat (action)` ON SCHEDULE EVERY 1 HOUR STARTS '2025-01-01 00:00:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    -- ==============================
    --  1. 建立暫存表，統計 5 個行為表的熱度
    -- ==============================
    CREATE TEMPORARY TABLE tmp_heat AS
    SELECT
        news_id,
        channel_id,
        eventsorting_id,
        multipleperspectives_id,
        SUM(CASE WHEN source='view' THEN heat ELSE 0 END) AS heat_view,
        SUM(CASE WHEN source='share' THEN heat ELSE 0 END) AS heat_share,
        SUM(CASE WHEN source='bookmark' THEN heat ELSE 0 END) AS heat_bookmark,
        SUM(CASE WHEN source='comment' THEN heat ELSE 0 END) AS heat_comment,
        SUM(CASE WHEN source='score' THEN heat ELSE 0 END) AS heat_score
    FROM (
        SELECT news_id, channel_id, eventsorting_id, multipleperspectives_id,
               100 * EXP(-(-LN(0.05)/36) * CEIL(TIMESTAMPDIFF(HOUR, created_at, NOW()))) AS heat,
               'view' AS source
        FROM user_view
        WHERE created_at >= NOW() - INTERVAL 36 HOUR

        UNION ALL
        SELECT news_id, channel_id, eventsorting_id, multipleperspectives_id,
               100 * EXP(-(-LN(0.05)/36) * CEIL(TIMESTAMPDIFF(HOUR, created_at, NOW()))) AS heat,
               'share' AS source
        FROM user_share
        WHERE created_at >= NOW() - INTERVAL 36 HOUR

        UNION ALL
        SELECT news_id, channel_id, eventsorting_id, multipleperspectives_id,
               100 * EXP(-(-LN(0.05)/36) * CEIL(TIMESTAMPDIFF(HOUR, created_at, NOW()))) AS heat,
               'bookmark' AS source
        FROM user_bookmark
        WHERE created_at >= NOW() - INTERVAL 36 HOUR

        UNION ALL
        SELECT news_id, channel_id, eventsorting_id, multipleperspectives_id,
               100 * EXP(-(-LN(0.05)/36) * CEIL(TIMESTAMPDIFF(HOUR, created_at, NOW()))) AS heat,
               'comment' AS source
        FROM user_comment
        WHERE created_at >= NOW() - INTERVAL 36 HOUR

        UNION ALL
        SELECT news_id, channel_id, eventsorting_id, multipleperspectives_id,
               100 * EXP(-(-LN(0.05)/36) * CEIL(TIMESTAMPDIFF(HOUR, created_at, NOW()))) AS heat,
               'score' AS source
        FROM user_score
        WHERE created_at >= NOW() - INTERVAL 36 HOUR
    ) t
    GROUP BY news_id, channel_id, eventsorting_id, multipleperspectives_id;

    -- ==============================
    --  2. 更新 news_data
    -- ==============================
    UPDATE news_data nd
    JOIN (
        SELECT news_id,
               SUM(heat_view)     AS recent_view,
               SUM(heat_share)    AS recent_share,
               SUM(heat_bookmark) AS recent_bookmark,
               SUM(heat_comment)  AS recent_comment,
               SUM(heat_score)    AS recent_score
        FROM tmp_heat
        GROUP BY news_id
    ) thn ON cd.news_id = thn.news_id
    SET nd.recent_view     = thn.recent_view,
        nd.recent_share    = thn.recent_share,
        nd.recent_bookmark = thn.recent_bookmark,
        nd.recent_comment  = thn.recent_comment,
        nd.recent_score    = thn.recent_score;

    -- ==============================
    --  3. 更新 channel_data
    -- ==============================
    UPDATE channel_data cd
    JOIN (
        SELECT channel_id,
               SUM(heat_view)     AS recent_view,
               SUM(heat_share)    AS recent_share,
               SUM(heat_bookmark) AS recent_bookmark,
               SUM(heat_comment)  AS recent_comment,
               SUM(heat_score)    AS recent_score
        FROM tmp_heat
        GROUP BY channel_id
    ) thc ON cd.channel_id = thc.channel_id
    SET cd.recent_view     = thc.recent_view,
        cd.recent_share    = thc.recent_share,
        cd.recent_bookmark = thc.recent_bookmark,
        cd.recent_comment  = thc.recent_comment,
        cd.recent_score    = thc.recent_score;

    -- ==============================
    --  4. 更新 eventsorting_data
    -- ==============================
    UPDATE eventsorting_data ed
    JOIN (
        SELECT eventsorting_id,
               SUM(heat_view)     AS recent_view,
               SUM(heat_share)    AS recent_share,
               SUM(heat_bookmark) AS recent_bookmark,
               SUM(heat_comment)  AS recent_comment,
               SUM(heat_score)    AS recent_score
        FROM tmp_heat
        GROUP BY eventsorting_id
    ) the ON ed.eventsorting_id = the.eventsorting_id
    SET ed.recent_view     = the.recent_view,
        ed.recent_share    = the.recent_share,
        ed.recent_bookmark = the.recent_bookmark,
        ed.recent_comment  = the.recent_comment,
        ed.recent_score    = the.recent_score;

    -- ==============================
    --  5. 更新 multipleperspectives_data
    -- ==============================
    UPDATE multipleperspectives_data md
    JOIN (
        SELECT multipleperspectives_id,
               SUM(heat_view)     AS recent_view,
               SUM(heat_share)    AS recent_share,
               SUM(heat_bookmark) AS recent_bookmark,
               SUM(heat_comment)  AS recent_comment,
               SUM(heat_score)    AS recent_score
        FROM tmp_heat
        GROUP BY multipleperspectives_id
    ) thm ON md.multipleperspectives_id = thm.multipleperspectives_id
    SET md.recent_view     = thm.recent_view,
        md.recent_share    = thm.recent_share,
        md.recent_bookmark = thm.recent_bookmark,
        md.recent_comment  = thm.recent_comment,
        md.recent_score    = thm.recent_score;

    DROP TEMPORARY TABLE IF EXISTS tmp_heat;

END$$

DELIMITER ;
COMMIT;

